 bmiTitle:'Body-Mass-Index',
 bmiLead:'Ein Verhältnis von Masse zu Körpergröße, keine Messung der Körperzusammensetzung. Es trennt Populationen gut und Einzelpersonen schlecht.',
 bmiW:'Gewicht kg', bmiHt:'Größe cm', bmiF:'BMI = kg / m²',
 bmiCat:['Untergewicht','Normalgewicht','Übergewicht','Adipositas I','Adipositas II','Adipositas III'],
 bmiNote:'<b>Was er nicht sieht.</b> Der BMI unterscheidet weder Fett von Muskel noch, wo das Fett sitzt. Eine muskulöse sportliche und eine sitzend lebende Person gleicher Größe und gleichen Gewichts erhalten dieselbe Zahl. Die WHO weist zudem darauf hin, dass das mit einem bestimmten BMI verbundene Risiko zwischen Populationen variiert und dass für Menschen asiatischer Herkunft niedrigere Handlungsschwellen, etwa 23 und 27,5, erwogen wurden.',
 bmiSrcs:[{u:U.whoBmi, s:'WHO Global Health Observatory — body mass index'}],

 pyTitle:'Packungsjahre', pyWord:'Packungsjahre',
 pyLead:'Kumulative Tabakexposition. Ein Packungsjahr entspricht zwanzig Zigaretten täglich über ein Jahr.',
 pyC:'Zigaretten/Tag', pyY:'Raucherjahre', pyU:'Packungsjahre',
 pyBand:['Unter den üblichen Schwellen','COPD-Risikoschwelle (GOLD)','Anspruch auf LDCT-Screening, 50–80 Jahre (USPSTF 2021)'],
 pyNote:'<b>Der übliche Fehler.</b> Der erste Term ist die Zahl der Zigaretten pro Tag geteilt durch zwanzig, nicht die Zahl der Packungen pro Tag. Wer 20 in das Packungsfeld einträgt, erhält eine zwanzigfach überhöhte Exposition. Zu beachten ist außerdem, dass die Screening-Schwelle bei <b>20</b> Packungsjahren liegt und nicht bei 30: Die USPSTF hat sie 2021 gesenkt, ältere Materialien nennen noch den früheren Wert.',
 pySrcs:[{u:U.uspstf, s:'US Preventive Services Task Force — Empfehlung zum Lungenkrebs-Screening (2021)'},
         {u:U.gold, s:'Global Initiative for Chronic Obstructive Lung Disease — GOLD-Bericht'}],

 paTitle:'Körperliche Aktivität',
 paLead:'Das WHO-Ziel wird in Äquivalentminuten mäßiger Intensität ausgedrückt, wobei intensive Aktivität doppelt zählt. Mit einer Altersangabe erscheinen die Herzfrequenzzonen.',
 paAge:'Alter Jahre', paM:'mäßig Min/Woche', paV:'intensiv Min/Woche', paU:'Äquivalentminuten/Woche',
 paF:'Äquivalent = mäßig + 2 × intensiv = ',
